/* eslint-disable react-hooks/refs */
/* eslint-disable no-unused-vars */
import { useState, useEffect, useRef, useCallback } from "react";
import { motion, AnimatePresence, Reorder } from "framer-motion";
import {
  X,
  FileCode2,
  FileJson,
  FileText,
  Braces,
  TestTube2,
  Sliders,
  Box,
  Lock,
  File,
  Loader2,
  AlertCircle,
  Save,
  Check,
  Sparkles,
  CheckCircle2,
  ChevronRight,
  Eye,
  EyeOff,
  Copy,
  WrapText,
  Layers,
  Code2,
  Terminal,
} from "lucide-react";
import MonacoEditor from "./editor/CollaborativeCodeEditor";
import { useTheme } from "../../contexts/ThemeContext";
import { GitPanel } from "./GitPanel";
import {
  getFileContentApi,
  updateFileContentApi,
} from "../../services/project.service";
import { getFileCoverage } from "../../services/coverage.service";
import { EditorCodeSkeleton } from "../common/Skeleton";
import { useProjectAccess } from "../../hooks/useProjectAccess";
import { useAuth } from "../../hooks/useAuth";
import FileConflictDialog from "./FileConflictDialog";
import { downloadEditorDraft } from "../../lib/editorDraft";

/* ── Smart File Icon Resolver ────────────────────────────── */
function getFileIcon(fileName = "") {
  const lower = fileName.toLowerCase();

  // Tests
  if (
    lower.endsWith(".spec.ts") ||
    lower.endsWith(".spec.js") ||
    lower.endsWith(".test.ts") ||
    lower.endsWith(".test.js") ||
    lower.endsWith(".spec.jsx") ||
    lower.endsWith(".test.jsx")
  ) {
    return <TestTube2 size={13} style={{ color: "#c084fc", flexShrink: 0 }} />;
  }

  // React & TypeScript
  if (lower.endsWith(".tsx")) {
    return <FileCode2 size={13} style={{ color: "#67e8f9", flexShrink: 0 }} />;
  }
  if (lower.endsWith(".jsx")) {
    return <FileCode2 size={13} style={{ color: "#22d3ee", flexShrink: 0 }} />;
  }
  if (lower.endsWith(".ts")) {
    return <Braces size={13} style={{ color: "#38bdf8", flexShrink: 0 }} />;
  }
  if (
    lower.endsWith(".js") ||
    lower.endsWith(".mjs") ||
    lower.endsWith(".cjs")
  ) {
    return <FileCode2 size={13} style={{ color: "#fbbf24", flexShrink: 0 }} />;
  }

  // Config files
  if (
    lower.includes(".config.") ||
    lower.startsWith("tsconfig") ||
    lower.startsWith("vite.config") ||
    lower.startsWith("tailwind") ||
    lower.startsWith("eslint")
  ) {
    return <Sliders size={13} style={{ color: "#facc15", flexShrink: 0 }} />;
  }

  // Package & JSON
  if (lower === "package.json" || lower === "package-lock.json") {
    return <Box size={13} style={{ color: "#fb923c", flexShrink: 0 }} />;
  }
  if (lower.endsWith(".json") || lower.endsWith(".jsonc")) {
    return <FileJson size={13} style={{ color: "#4ade80", flexShrink: 0 }} />;
  }

  // Styles
  if (
    lower.endsWith(".css") ||
    lower.endsWith(".scss") ||
    lower.endsWith(".sass") ||
    lower.endsWith(".less")
  ) {
    return <FileText size={13} style={{ color: "#f472b6", flexShrink: 0 }} />;
  }

  // HTML
  if (lower.endsWith(".html") || lower.endsWith(".htm")) {
    return <FileCode2 size={13} style={{ color: "#fb923c", flexShrink: 0 }} />;
  }

  // Markdown & Docs
  if (
    lower.endsWith(".md") ||
    lower.endsWith(".markdown") ||
    lower.endsWith(".txt")
  ) {
    return <FileText size={13} style={{ color: "#38bdf8", flexShrink: 0 }} />;
  }

  // Git / Env / Lock
  if (
    lower.startsWith(".git") ||
    lower.startsWith(".env") ||
    lower.endsWith(".lock")
  ) {
    return <Lock size={13} style={{ color: "#86efac", flexShrink: 0 }} />;
  }

  return <File size={13} style={{ color: "#94a3b8", flexShrink: 0 }} />;
}

/* ── Extension to Language Mapping ───────────────────────── */
const EXT_LANG_MAP = {
  ".js": "javascript",
  ".jsx": "javascript",
  ".ts": "typescript",
  ".tsx": "typescript",
  ".json": "json",
  ".css": "css",
  ".html": "html",
  ".md": "markdown",
  ".py": "python",
  ".java": "java",
  ".yml": "yaml",
  ".yaml": "yaml",
  ".xml": "xml",
  ".sh": "shell",
  ".bash": "shell",
  ".txt": "text",
};

export const isTestFile = (filePath) => {
  if (!filePath) return false;
  const normalized = filePath.replace(/\\/g, "/").toLowerCase();
  return (
    /(^|\/)(tests?|__tests__|spec|cypress|e2e)\//i.test(normalized) ||
    /\.(test|spec)\.[a-z0-9]+$/i.test(normalized)
  );
};

/* ── Tab Component (Reorderable with Drag & Drop) ────────── */
function ReorderableTab({ tab, isActive, onSelect, onClose }) {
  const [hovered, setHovered] = useState(false);
  const icon = getFileIcon(tab.name);

  return (
    <Reorder.Item
      as="div"
      key={tab.id}
      value={tab}
      id={`tab-${tab.id}`}
      layout
      initial={{ opacity: 0, x: -6 }}
      animate={{ opacity: 1, x: 0 }}
      exit={{ opacity: 0, x: -6, width: 0 }}
      whileDrag={{
        scale: 1.02,
        zIndex: 50,
        boxShadow: "0 4px 12px rgba(0, 0, 0, 0.25)",
        cursor: "grabbing",
      }}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onClick={() => onSelect(tab.id)}
      className="relative flex items-center gap-2 h-full cursor-grab select-none group flex-shrink-0"
      style={{
        minWidth: 120,
        maxWidth: 200,
        padding: "0 12px",
        background: isActive ? "var(--color-bg)" : "transparent",
        color: isActive ? "var(--color-text)" : "var(--color-text-secondary)",
        borderRight: "1px solid var(--color-border)",
        fontFamily: "var(--font-sans)",
        fontSize: 12,
        fontWeight: isActive ? 500 : 400,
        transition: "background 0.15s ease, color 0.15s ease",
      }}
    >
      {/* Active Top Highlight Line */}
      {isActive && (
        <motion.div
          layoutId="tab-top-indicator"
          className="absolute top-0 left-0 right-0"
          style={{
            height: 2,
            background: "var(--color-primary)",
          }}
        />
      )}

      {/* File Icon */}
      {icon}

      {/* File Name */}
      <span className="truncate flex-1 min-w-0">{tab.name}</span>

      {/* Unsaved indicator or Close Button */}
      <div
        className="flex items-center justify-center flex-shrink-0 ml-1"
        style={{ width: 16, height: 16 }}
      >
        {tab.unsaved ? (
          <span
            style={{
              width: 7,
              height: 7,
              borderRadius: "50%",
              background: "var(--color-primary)",
              display: "inline-block",
            }}
          />
        ) : (
          <motion.button
            animate={{ opacity: hovered || isActive ? 1 : 0 }}
            transition={{ duration: 0.1 }}
            onClick={(e) => {
              e.stopPropagation();
              onClose(tab.id);
            }}
            whileHover={{ scale: 1.15, background: "rgba(255,255,255,0.12)" }}
            whileTap={{ scale: 0.9 }}
            className="p-0.5 rounded cursor-pointer flex items-center justify-center"
            style={{
              color: "#8b949e",
              background: "transparent",
              border: "none",
            }}
            title="Close (Ctrl+W)"
          >
            <X size={12} />
          </motion.button>
        )}
      </div>
    </Reorder.Item>
  );
}

/* ── Rich Markdown Previewer ─────────────────────────────── */
function MarkdownPreview({ content }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const renderLines = () => {
    if (!content)
      return <p className="text-gray-500 italic">No content to preview.</p>;

    const lines = content.split("\n");
    let inCodeBlock = false;
    let codeContent = [];
    let codeLang = "";
    const elements = [];

    lines.forEach((line, idx) => {
      if (line.startsWith("```")) {
        if (!inCodeBlock) {
          inCodeBlock = true;
          codeLang = line.slice(3).trim();
          codeContent = [];
        } else {
          inCodeBlock = false;
          elements.push(
            <div
              key={`code-${idx}`}
              className="my-3 rounded-lg overflow-hidden"
              style={{
                background: "var(--color-surface)",
                border: "1px solid var(--color-border)",
              }}
            >
              <div
                className="flex items-center justify-between px-3 py-1.5"
                style={{
                  background: "var(--color-bg)",
                  borderBottom: "1px solid var(--color-border)",
                  fontSize: 11,
                  color: "var(--color-text-secondary)",
                }}
              >
                <span>{codeLang || "text"}</span>
              </div>
              <pre
                className="p-3 text-xs overflow-x-auto m-0"
                style={{
                  fontFamily: "var(--font-mono)",
                  color: "var(--color-text)",
                  lineHeight: 1.6,
                }}
              >
                <code>{codeContent.join("\n")}</code>
              </pre>
            </div>,
          );
        }
        return;
      }

      if (inCodeBlock) {
        codeContent.push(line);
        return;
      }

      const trimmed = line.trim();
      if (!trimmed) {
        elements.push(<div key={`empty-${idx}`} className="h-2" />);
        return;
      }

      if (trimmed.startsWith("# ")) {
        elements.push(
          <h1
            key={idx}
            className="text-xl font-bold pb-2 mb-3 mt-4"
            style={{
              color: "var(--color-text)",
              borderBottom: "1px solid var(--color-border)",
            }}
          >
            {trimmed.slice(2)}
          </h1>,
        );
        return;
      }

      if (trimmed.startsWith("## ")) {
        elements.push(
          <h2
            key={idx}
            className="text-base font-semibold pb-1 mb-2 mt-4"
            style={{
              color: "var(--color-text)",
              borderBottom: "1px solid var(--color-border)",
            }}
          >
            {trimmed.slice(3)}
          </h2>,
        );
        return;
      }

      if (trimmed.startsWith("### ")) {
        elements.push(
          <h3
            key={idx}
            className="text-sm font-semibold mb-1 mt-3"
            style={{ color: "var(--color-primary)" }}
          >
            {trimmed.slice(4)}
          </h3>,
        );
        return;
      }

      if (trimmed.startsWith("- ") || trimmed.startsWith("* ")) {
        elements.push(
          <div
            key={idx}
            className="flex items-start gap-2 text-sm pl-2 py-0.5"
            style={{ color: "var(--color-text)" }}
          >
            <span
              style={{
                width: 4,
                height: 4,
                borderRadius: "50%",
                background: "var(--color-primary)",
                marginTop: 8,
                flexShrink: 0,
              }}
            />
            <span>{trimmed.slice(2)}</span>
          </div>,
        );
        return;
      }

      elements.push(
        <p
          key={idx}
          className="text-sm leading-relaxed m-0 py-0.5"
          style={{ color: "var(--color-text)" }}
        >
          {line}
        </p>,
      );
    });

    return elements;
  };

  return (
    <div
      className="flex-1 overflow-y-auto p-8 custom-scrollbar"
      style={{
        background: "var(--color-bg)",
        maxWidth: 900,
        margin: "0 auto",
        width: "100%",
        color: "var(--color-text)",
      }}
    >
      <div
        className="flex items-center justify-between pb-4 mb-4"
        style={{ borderBottom: "1px solid var(--color-border)" }}
      >
        <div className="flex items-center gap-2">
          <FileText size={16} style={{ color: "var(--color-primary)" }} />
          <span
            className="text-xs font-semibold uppercase tracking-wider"
            style={{ color: "var(--color-text-secondary)" }}
          >
            Markdown Preview
          </span>
        </div>
        <button
          onClick={handleCopy}
          className="flex items-center gap-1.5 px-2.5 py-1 rounded text-xs transition-colors cursor-pointer"
          style={{
            color: "var(--color-text-secondary)",
            background: "var(--color-surface)",
            border: "1px solid var(--color-border)",
          }}
        >
          {copied ? (
            <Check size={12} className="text-green-400" />
          ) : (
            <Copy size={12} />
          )}
          <span>{copied ? "Copied" : "Copy Markdown"}</span>
        </button>
      </div>

      <div className="space-y-1">{renderLines()}</div>
    </div>
  );
}

/* ── Main Editor Component ───────────────────────────────── */
export default function Editor({
  tabs,
  activeTabId,
  onSelectTab,
  onCloseTab,
  onReorderTabs,
  fileTree = [],
  isLoadingTree,
  projectId,
  snapshotId,
  coverageType = "unit",
  onOpenFile,
  onRunAnalysis,
  onSuggestTestcase,
  refreshTrigger,
  jumpTarget,
}) {
  const { resolvedTheme } = useTheme();
  const projectAccess = useProjectAccess(projectId);
  const { userId: draftUserId } = useAuth();
  const canEdit = projectAccess.can("files.write");
  const [conflict, setConflict] = useState(null);
  const [fileContents, setFileContents] = useState({});
  const fetchedRef = useRef(new Set());
  const saveHandlerRef = useRef(null);
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState("");
  const [showGitPanel, setShowGitPanel] = useState(false);
  const draftStorageKey = useCallback(path => `covai_draft_${draftUserId}_${projectId}_${snapshotId}_${path}`, [draftUserId, projectId, snapshotId]);
  useEffect(() => {
    if (!draftUserId || !projectId) return;
    for (const [path, file] of Object.entries(fileContents)) {
      const key = `covai_draft_${draftUserId}_${projectId}_${snapshotId}_${path}`;
      if (file.draft !== undefined && file.draft !== file.content) {
        sessionStorage.setItem(key, JSON.stringify({ draft: file.draft, version: file.version, snapshotId: file.snapshotId }));
      } else if (file.content !== undefined) sessionStorage.removeItem(key);
    }
  }, [draftUserId, projectId, snapshotId, fileContents]);

  // Invalidate cache and reload current file when external sync occurs (e.g. Git pull / checkout)
  useEffect(() => {
    if (refreshTrigger) {
      fetchedRef.current.clear();
      setFileContents(previous => Object.fromEntries(Object.entries(previous).filter(([, file]) => file.draft !== undefined && file.draft !== file.content)));
    }
  }, [refreshTrigger]);

  // Coverage state
  const [fileCoverage, setFileCoverage] = useState(null);
  const [isLoadingCoverage, setIsLoadingCoverage] = useState(false);
  const [appliedNotification, setAppliedNotification] = useState(null);

  const editorRef = useRef(null);
  const monacoRef = useRef(null);
  const decorationsCollectionRef = useRef(null);
  const jumpDecorationsRef = useRef([]);
  const [editorMountCount, setEditorMountCount] = useState(0);

  // Handle jumpTarget navigation (e.g. from Function Coverage "Open code" or CFG "Open in Editor")
  useEffect(() => {
    if (!jumpTarget || !editorRef.current || !monacoRef.current) return;
    if (!activeTabId || !jumpTarget.filePath) return;

    const normActive = activeTabId.replace(/\\/g, "/").toLowerCase();
    const normTarget = jumpTarget.filePath.replace(/\\/g, "/").toLowerCase();

    // Check if active file matches target
    const isMatched =
      normActive === normTarget ||
      normActive.endsWith("/" + normTarget) ||
      normTarget.endsWith("/" + normActive) ||
      normActive.split("/").pop() === normTarget.split("/").pop();

    if (!isMatched) return;

    const editor = editorRef.current;
    const monaco = monacoRef.current;
    const line = Math.max(1, Number(jumpTarget.line) || 1);
    const endLine = Math.max(line, Number(jumpTarget.endLine) || line);

    // Wait until model is available with loaded lines
    const model = editor.getModel();
    if (!model) return;

    const fileText = currentFile.draft ?? currentFile.content;
    if (typeof fileText === "string" && fileText.length > 0 && model.getValueLength() === 0) {
      model.setValue(fileText);
    }

    const lineCount = model.getLineCount();
    const safeLine = Math.min(line, Math.max(1, lineCount));
    const safeEndLine = Math.min(endLine, Math.max(1, lineCount));

    editor.revealLineInCenter(safeLine);
    editor.setPosition({ lineNumber: safeLine, column: 1 });

    const newDecorations = [
      {
        range: new monaco.Range(safeLine, 1, safeEndLine, 1),
        options: {
          isWholeLine: true,
          className: "monaco-function-active-range",
          marginClassName: "monaco-function-glyph-marker",
          linesDecorationsClassName: "monaco-function-line-number-active",
        },
      },
    ];

    jumpDecorationsRef.current = editor.deltaDecorations(
      jumpDecorationsRef.current,
      newDecorations
    );

    editor.focus();

    const timer = setTimeout(() => {
      if (editorRef.current) {
        jumpDecorationsRef.current = editorRef.current.deltaDecorations(
          jumpDecorationsRef.current,
          []
        );
      }
    }, 3500);

    return () => clearTimeout(timer);
  }, [jumpTarget, activeTabId, fileContents, editorMountCount]);

  const isCurrentTestFile = isTestFile(activeTabId);

  // Fetch file coverage when active tab or snapshot changes
  useEffect(() => {
    if (!activeTabId || !snapshotId || isCurrentTestFile) {
      setFileCoverage(null);
      return;
    }

    let isMounted = true;
    setIsLoadingCoverage(true);

    getFileCoverage(snapshotId, activeTabId)
      .then((res) => {
        if (!isMounted) return;
        setFileCoverage(res?.data || null);
      })
      .catch(() => {
        if (!isMounted) return;
        setFileCoverage(null);
      })
      .finally(() => {
        if (isMounted) setIsLoadingCoverage(false);
      });

    return () => {
      isMounted = false;
    };
  }, [activeTabId, snapshotId, isCurrentTestFile]);

  // Editor View Preferences
  const [wordWrap, setWordWrap] = useState(true);
  const [showMinimap, setShowMinimap] = useState(false);
  const [previewMode, setPreviewMode] = useState(false);
  const [cursorPos, setCursorPos] = useState({ line: 1, col: 1 });
  const [copiedCode, setCopiedCode] = useState(false);

  // Fetch file content when active tab changes
  useEffect(() => {
    if (!activeTabId || !projectId) return;

    if (
      fileContents[activeTabId]?.content !== undefined ||
      fileContents[activeTabId]?.loading
    )
      return;
    if (fetchedRef.current.has(activeTabId)) return;

    fetchedRef.current.add(activeTabId);

    setFileContents((prev) => ({
      ...prev,
      [activeTabId]: { content: undefined, loading: true, error: null },
    }));

    getFileContentApi(projectId, activeTabId, { snapshotId })
      .then((res) => {
        let recovered = null;
        try { recovered = JSON.parse(sessionStorage.getItem(draftStorageKey(activeTabId)) || "null"); } catch { /* Invalid local recovery data is ignored. */ }
        setFileContents((prev) => ({
          ...prev,
          [activeTabId]: {
            content: res.data.content,
            version: recovered?.version || res.data.version,
            draft: typeof recovered?.draft === "string" ? recovered.draft : undefined,
            snapshotId: res.data.snapshotId,
            workspaceRevision: res.data.workspaceRevision,
            loading: false,
            error: null,
          },
        }));
      })
      .catch((err) => {
        setFileContents((prev) => ({
          ...prev,
          [activeTabId]: {
            content: undefined,
            loading: false,
            error: err.message || "Failed to load file",
          },
        }));
      });
  }, [activeTabId, projectId, snapshotId, fileContents, draftStorageKey]);

  const currentFile = fileContents[activeTabId] || {};
  const activeTab = tabs.find((t) => t.id === activeTabId);

  // Update Monaco decorations for coverage gutters (✓, ⚑, ×)
  useEffect(() => {
    const editor = editorRef.current;
    const monaco = monacoRef.current;
    if (!editor || !monaco) return;

    if (decorationsCollectionRef.current) {
      if (typeof decorationsCollectionRef.current.clear === "function") {
        decorationsCollectionRef.current.clear();
      } else if (Array.isArray(decorationsCollectionRef.current)) {
        editor.deltaDecorations(decorationsCollectionRef.current, []);
        decorationsCollectionRef.current = [];
      }
    }

    if (isCurrentTestFile || !fileCoverage || !fileCoverage.lines) return;

    const decorations = [];
    const lineEntries = Object.entries(fileCoverage.lines);

    for (const [lineStr, info] of lineEntries) {
      const lineNum = Number(lineStr);
      if (isNaN(lineNum) || lineNum < 1) continue;

      let glyphMarginClassName = "";
      let className = "";
      let hoverText = "";

      if (info.status === "failed") {
        glyphMarginClassName = "coverage-glyph-failed";
        className = "coverage-line-failed";
        hoverText = `**× Test Assertion Failed** on line ${lineNum}\n\n${info.error || "Assertion failure in test run"}${info.details ? `\n\n\`\`\`\n${info.details.slice(0, 300)}\n\`\`\`` : ""}`;
      } else if (info.status === "uncovered") {
        glyphMarginClassName = "coverage-glyph-uncovered";
        className = "coverage-line-uncovered";
        hoverText = `**⚑ Uncovered** (Line ${lineNum})\n\n${info.reason || "Not executed by any unit tests"}`;
      } else if (info.status === "covered") {
        glyphMarginClassName = "coverage-glyph-passed";
        hoverText = `**✓ Covered** (Line ${lineNum})\n\nExecuted by tests (${info.hits || 1} hits)`;
      }

      if (glyphMarginClassName) {
        decorations.push({
          range: new monaco.Range(lineNum, 1, lineNum, 1),
          options: {
            isWholeLine: true,
            glyphMarginClassName,
            className: className || undefined,
            glyphMarginHoverMessage: hoverText
              ? { value: hoverText }
              : undefined,
          },
        });
      }
    }

    if (typeof editor.createDecorationsCollection === "function") {
      decorationsCollectionRef.current =
        editor.createDecorationsCollection(decorations);
    } else {
      decorationsCollectionRef.current = editor.deltaDecorations(
        [],
        decorations,
      );
    }
  }, [fileCoverage, activeTabId, currentFile.content, isCurrentTestFile]);

  // Determine language
  const ext = activeTab ? "." + activeTab.name.split(".").pop() : "";
  const lang = EXT_LANG_MAP[ext.toLowerCase()] || "text";
  const isMarkdown =
    ext.toLowerCase() === ".md" || ext.toLowerCase() === ".markdown";

  // Build breadcrumb
  const breadcrumb = activeTabId ? activeTabId.split("/") : [];

  const handleChange = (value) => {
    if (!canEdit) return;
    setSaveError("");
    setFileContents((prev) => ({
      ...prev,
      [activeTabId]: { ...prev[activeTabId], draft: value ?? "" },
    }));
  };

  const handleSave = async () => {
    const file = fileContents[activeTabId];
    if (
      !projectId ||
      !canEdit ||
      !activeTabId ||
      !file ||
      file.draft === undefined ||
      saving
    )
      return;

    setSaving(true);
    setSaveError("");
    try {
      const saved = await updateFileContentApi(projectId, activeTabId, file.draft, { snapshotId: file.snapshotId, expectedVersion: file.version, expectedWorkspaceRevision: file.workspaceRevision });
      setFileContents((prev) => ({
        ...prev,
        [activeTabId]: {
          ...prev[activeTabId],
          content: file.draft,
          draft: prev[activeTabId]?.draft === file.draft ? undefined : prev[activeTabId]?.draft,
          version: saved.data?.version,
          workspaceRevision: saved.data?.workspaceRevision,
        },
      }));
    } catch (err) {
      if (err.status === 409) setConflict({ projectId, original: file.content, path: activeTabId, draft: file.draft, snapshotId: file.snapshotId, details: err.details });
      setSaveError(err.message || "Could not save file");
    } finally {
      setSaving(false);
    }
  };

  saveHandlerRef.current = handleSave;

  const handleCopyCurrentCode = () => {
    const code = editorRef.current?.getValue() ?? currentFile.draft ?? currentFile.content ?? "";
    if (!code) return;
    navigator.clipboard.writeText(code);
    setCopiedCode(true);
    setTimeout(() => setCopiedCode(false), 2000);
  };

  const hasUnsavedChanges =
    currentFile.draft !== undefined &&
    currentFile.draft !== currentFile.content;

  const covPctColor = (pct) =>
    pct >= 80 ? "#22c55e" : pct >= 60 ? "#fbbf24" : "#f87171";

  // Configure custom Monaco Theme
  const handleEditorWillMount = (monaco) => {
    monaco.editor.defineTheme("covai-dark", {
      base: "vs-dark",
      inherit: true,
      rules: [
        { token: "comment", foreground: "6e7681", fontStyle: "italic" },
        { token: "keyword", foreground: "c084fc", fontStyle: "bold" },
        { token: "identifier", foreground: "e6edf3" },
        { token: "string", foreground: "7ee787" },
        { token: "number", foreground: "fca5a5" },
        { token: "type", foreground: "67e8f9" },
        { token: "function", foreground: "93c5fd" },
        { token: "delimiter", foreground: "8b949e" },
      ],
      colors: {
        "editor.background": "#0d1117",
        "editor.foreground": "#e6edf3",
        "editor.lineHighlightBackground": "#161b2280",
        "editor.lineHighlightBorder": "#00000000",
        "editorCursor.foreground": "#a78bfa",
        "editorWhitespace.foreground": "#21262d",
        "editorIndentGuide.background": "#21262d",
        "editorIndentGuide.activeBackground": "#7c3aed60",
        "editorLineNumber.foreground": "#484f58",
        "editorLineNumber.activeForeground": "#c4b5fd",
        "scrollbarSlider.background": "#7c3aed20",
        "scrollbarSlider.hoverBackground": "#7c3aed50",
        "scrollbarSlider.activeBackground": "#7c3aed80",
        "editor.selectionBackground": "#7c3aed35",
        "editor.inactiveSelectionBackground": "#7c3aed20",
      },
    });

    monaco.editor.defineTheme("covai-light", {
      base: "vs",
      inherit: true,
      rules: [
        { token: "comment", foreground: "6a737d", fontStyle: "italic" },
        { token: "keyword", foreground: "7c3aed", fontStyle: "bold" },
        { token: "identifier", foreground: "24292e" },
        { token: "string", foreground: "032f62" },
        { token: "number", foreground: "005cc5" },
        { token: "type", foreground: "0891b2" },
        { token: "function", foreground: "2563eb" },
        { token: "delimiter", foreground: "586069" },
      ],
      colors: {
        "editor.background": "#ffffff",
        "editor.foreground": "#24292e",
        "editor.lineHighlightBackground": "#f6f8fa",
        "editor.lineHighlightBorder": "#00000000",
        "editorCursor.foreground": "#7c3aed",
        "editorWhitespace.foreground": "#e1e4e8",
        "editorIndentGuide.background": "#e1e4e8",
        "editorIndentGuide.activeBackground": "#7c3aed40",
        "editorLineNumber.foreground": "#959da5",
        "editorLineNumber.activeForeground": "#7c3aed",
        "scrollbarSlider.background": "#00000015",
        "scrollbarSlider.hoverBackground": "#00000030",
        "scrollbarSlider.activeBackground": "#00000045",
        "editor.selectionBackground": "#7c3aed25",
        "editor.inactiveSelectionBackground": "#7c3aed15",
      },
    });
  };

  const handleEditorDidMount = (editor, monaco) => {
    editorRef.current = editor;
    monacoRef.current = monaco;
    setEditorMountCount((c) => c + 1);

    // Save shortcut
    editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyS, () =>
      saveHandlerRef.current?.(),
    );

    // Track cursor position
    editor.onDidChangeCursorPosition((e) => {
      setCursorPos({
        line: e.position.lineNumber,
        col: e.position.column,
      });
    });
  };

  // Empty state: No files found in workspace
  if (!isLoadingTree && fileTree.length === 0) {
    return (
      <motion.div
        className="flex flex-col flex-1 h-full min-w-0 items-center justify-center p-6 text-center"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        style={{ background: "var(--color-bg)" }}
      >
        <div
          className="flex items-center justify-center w-14 h-14 rounded-2xl mb-4"
          style={{
            background: "var(--color-surface)",
            border: "1px solid var(--color-border)",
          }}
        >
          <Code2 size={26} style={{ color: "var(--color-primary)" }} />
        </div>
        <div
          style={{ color: "var(--color-text)", fontSize: 18, fontWeight: 600 }}
        >
          No workspace files detected
        </div>
        <div
          style={{
            color: "var(--color-text-secondary)",
            fontSize: 13,
            marginTop: 6,
            maxWidth: 360,
          }}
        >
          Import your repository or wait for the source code extraction process
          to complete.
        </div>
      </motion.div>
    );
  }

  // Empty state: No tabs open
  if (tabs.length === 0) {
    return (
      <motion.div
        className="flex flex-col flex-1 h-full min-w-0 items-center justify-center p-6 text-center select-none"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        style={{ background: "var(--color-bg)" }}
      >
        <div
          className="flex items-center justify-center w-14 h-14 rounded-xl mb-4"
          style={{
            background: "var(--color-surface)",
            border: "1px solid var(--color-border)",
          }}
        >
          <Sparkles size={24} style={{ color: "var(--color-primary)" }} />
        </div>

        <div
          style={{ color: "var(--color-text)", fontSize: 18, fontWeight: 600 }}
        >
          Welcome to TestCovAI Editor
        </div>
        <div
          style={{
            color: "var(--color-text-secondary)",
            fontSize: 13,
            marginTop: 6,
            maxWidth: 380,
            lineHeight: 1.6,
          }}
        >
          Select a file from the explorer on the left to start viewing, editing,
          or generating comprehensive tests.
        </div>

        {/* Shortcut Hints */}
        <div
          className="flex items-center gap-4 mt-6 text-xs"
          style={{ color: "var(--color-text-secondary)" }}
        >
          <div
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border"
            style={{
              background: "var(--color-surface)",
              borderColor: "var(--color-border)",
            }}
          >
            <kbd
              className="px-1.5 py-0.5 rounded font-mono text-[11px]"
              style={{
                background: "var(--color-bg)",
                border: "1px solid var(--color-border)",
                color: "var(--color-primary)",
              }}
            >
              Ctrl + S
            </kbd>
            <span>Save file</span>
          </div>
          <div
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border"
            style={{
              background: "var(--color-surface)",
              borderColor: "var(--color-border)",
            }}
          >
            <kbd
              className="px-1.5 py-0.5 rounded font-mono text-[11px]"
              style={{
                background: "var(--color-bg)",
                border: "1px solid var(--color-border)",
                color: "var(--color-primary)",
              }}
            >
              Alt + Z
            </kbd>
            <span>Toggle wrap</span>
          </div>
        </div>
      </motion.div>
    );
  }

  const codeContent = currentFile.draft ?? currentFile.content ?? "";
  const totalLines = codeContent ? codeContent.split("\n").length : 0;

  return (
    <motion.div
      className="flex flex-col flex-1 h-full min-w-0"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.2 }}
      style={{ background: "var(--color-bg)" }}
    >
      {/* ── Tab Bar ──────────────────────────────────────── */}
      <div
        className="flex items-center justify-between flex-shrink-0"
        style={{
          height: 38,
          background: "var(--color-surface)",
          borderBottom: "1px solid var(--color-border)",
        }}
      >
        {/* Left: Drag & Drop Reorderable Tabs */}
        <Reorder.Group
          as="div"
          axis="x"
          values={tabs}
          onReorder={(newTabs) => {
            if (onReorderTabs) {
              onReorderTabs(newTabs);
            }
          }}
          className="flex items-center h-full overflow-x-auto flex-1 min-w-0 custom-scrollbar"
          style={{ listStyle: "none", margin: 0, padding: 0 }}
        >
          <AnimatePresence mode="popLayout">
            {tabs.map((tab) => (
              <ReorderableTab
                key={tab.id}
                tab={tab}
                isActive={tab.id === activeTabId}
                onSelect={onSelectTab}
                onClose={onCloseTab}
              />
            ))}
          </AnimatePresence>
        </Reorder.Group>

        {/* Right: Quick Action Controls */}
        <div className="flex items-center gap-1 px-3 flex-shrink-0">
          {/* Markdown Preview Toggle */}
          {isMarkdown && (
            <button
              onClick={() => setPreviewMode(!previewMode)}
              className="flex items-center gap-1.5 px-2.5 py-1 rounded text-xs transition-colors cursor-pointer"
              style={{
                color: previewMode
                  ? "var(--color-primary)"
                  : "var(--color-text-secondary)",
                background: previewMode
                  ? "var(--color-surface)"
                  : "transparent",
                border: previewMode
                  ? "1px solid var(--color-border)"
                  : "1px solid transparent",
              }}
              title={
                previewMode
                  ? "Switch to Code View"
                  : "Switch to Markdown Preview"
              }
            >
              {previewMode ? <EyeOff size={13} /> : <Eye size={13} />}
              <span>{previewMode ? "Code" : "Preview"}</span>
            </button>
          )}

          {/* Word Wrap Toggle */}
          {!previewMode && (
            <button
              onClick={() => setWordWrap(!wordWrap)}
              className="flex items-center gap-1 p-1.5 rounded text-xs transition-colors cursor-pointer"
              style={{
                color: wordWrap
                  ? "var(--color-primary)"
                  : "var(--color-text-secondary)",
                background: wordWrap ? "var(--color-surface)" : "transparent",
                border: wordWrap
                  ? "1px solid var(--color-border)"
                  : "1px solid transparent",
              }}
              title={`Word Wrap: ${wordWrap ? "ON" : "OFF"} (Alt+Z)`}
            >
              <WrapText size={14} />
            </button>
          )}

          {/* Copy Code */}
          <button
            onClick={handleCopyCurrentCode}
            className="flex items-center gap-1 p-1.5 rounded text-xs transition-colors cursor-pointer"
            style={{
              color: "var(--color-text-secondary)",
              background: "transparent",
              border: "none",
            }}
            title="Copy all code"
          >
            {copiedCode ? (
              <Check size={14} style={{ color: "var(--color-success)" }} />
            ) : (
              <Copy size={14} />
            )}
          </button>
        </div>
      </div>

      {/* ── Breadcrumb & Action Header ────────────────────── */}
      <div
        className="flex items-center justify-between flex-shrink-0"
        style={{
          minHeight: 32,
          padding: "4px 16px",
          borderBottom: "1px solid var(--color-border)",
          background: "var(--color-surface)",
          fontSize: 12,
          fontFamily: "var(--font-sans)",
        }}
      >
        {/* Left: Path Segments */}
        <div className="flex items-center gap-1 overflow-hidden truncate">
          {getFileIcon(activeTab?.name)}
          {breadcrumb.map((crumb, i) => (
            <span key={i} className="flex items-center">
              {i > 0 && (
                <ChevronRight
                  size={11}
                  style={{
                    margin: "0 2px",
                    color: "var(--color-text-secondary)",
                  }}
                />
              )}
              <span
                style={{
                  color:
                    i === breadcrumb.length - 1
                      ? "var(--color-text)"
                      : "var(--color-text-secondary)",
                  fontWeight: i === breadcrumb.length - 1 ? 500 : 400,
                }}
              >
                {crumb}
              </span>
            </span>
          ))}
        </div>

        {/* Right: Coverage summary tags, Suggest testcase & Save Status */}
        <div className="flex items-center gap-2.5">
          {!isCurrentTestFile && fileCoverage?.summary && (
            <div
              className="flex items-center gap-2 text-xs"
              style={{ fontFamily: "var(--font-mono)" }}
            >
              <span
                className="px-2 py-0.5 rounded"
                style={{
                  background: "var(--color-bg)",
                  color: covPctColor(fileCoverage.summary.linesPct),
                  border: "1px solid var(--color-border)",
                }}
                title="Line Coverage"
              >
                Lines: {fileCoverage.summary.linesPct}%
              </span>
              <span
                className="px-2 py-0.5 rounded"
                style={{
                  background: "var(--color-bg)",
                  color: covPctColor(fileCoverage.summary.branchesPct),
                  border: "1px solid var(--color-border)",
                }}
                title="Branch Coverage"
              >
                Branches: {fileCoverage.summary.branchesPct}%
              </span>
              <span
                className="px-2 py-0.5 rounded"
                style={{
                  background: "var(--color-bg)",
                  color: covPctColor(fileCoverage.summary.stmtsPct),
                  border: "1px solid var(--color-border)",
                }}
                title="Statement Coverage"
              >
                Stmts: {fileCoverage.summary.stmtsPct}%
              </span>
            </div>
          )}

          {snapshotId && !isCurrentTestFile && (
            <button
              type="button"
              onClick={() => { if (projectAccess.can("ai.use")) onSuggestTestcase?.(activeTabId); }}
              disabled={!projectAccess.can("ai.use")}
              className="flex items-center gap-1.5 rounded px-2.5 py-1 text-xs font-semibold"
              style={{
                background: "rgba(168, 85, 247, 0.15)",
                color: "#c084fc",
                border: "1px solid rgba(168, 85, 247, 0.35)",
                cursor: "pointer",
                transition: "all 0.15s ease",
              }}
              title="Request AI Agent to suggest Jest/Vitest testcase in chat"
            >
              <Sparkles size={12} style={{ color: "#c084fc" }} />
              <span>Suggest testcase</span>
            </button>
          )}
          {saveError && (
            <span style={{ color: "var(--color-danger)", fontSize: 11 }}>
              {saveError}
            </span>
          )}

          <button
            type="button"
            onClick={handleSave}
            disabled={!canEdit || !hasUnsavedChanges || saving}
            className="flex items-center gap-1.5 rounded-md px-2.5 py-1 text-xs transition-all"
            style={{
              color: hasUnsavedChanges ? "#fff" : "var(--color-text-secondary)",
              background: hasUnsavedChanges
                ? "var(--color-primary)"
                : "transparent",
              border: hasUnsavedChanges
                ? "1px solid transparent"
                : "1px solid var(--color-border)",
              boxShadow: "none",
              cursor: hasUnsavedChanges && !saving ? "pointer" : "default",
            }}
            title="Save changes (Ctrl/Cmd + S)"
          >
            {saving ? (
              <Loader2 size={12} className="animate-spin text-white" />
            ) : hasUnsavedChanges ? (
              <Save size={12} />
            ) : (
              <Check size={12} style={{ color: "var(--color-success)" }} />
            )}
            <span>
              {saving ? "Saving..." : hasUnsavedChanges ? "Save" : "Saved"}
            </span>
          </button>
        </div>
      </div>

      {/* ── Applied Notification Banner ─────────────────────── */}
      {appliedNotification && (
        <div
          className="flex items-center justify-between px-4 py-2 text-xs flex-shrink-0"
          style={{
            background: "var(--color-surface)",
            borderBottom: "1px solid var(--color-border)",
            color: "var(--color-text)",
          }}
        >
          <div className="flex items-center gap-2">
            <CheckCircle2
              size={15}
              style={{ color: "var(--color-success)", flexShrink: 0 }}
            />
            <span>
              Applied test case to file{" "}
              <strong style={{ color: "var(--color-text)" }}>
                {appliedNotification.targetTestFile}
              </strong>
              . Review the draft code and click <strong>Run Analysis Unit</strong> to
              confirm tests pass and coverage increases.
            </span>
          </div>
          <div className="flex items-center gap-2">
            {onRunAnalysis && (
              <button
                type="button"
                onClick={() => {
                  setAppliedNotification(null);
                  onRunAnalysis();
                }}
                className="px-3 py-1 rounded font-semibold text-xs transition-colors cursor-pointer"
                style={{
                  background: "var(--color-primary)",
                  color: "#ffffff",
                  border: "none",
                }}
              >
                Run Analysis Unit
              </button>
            )}
            <button
              type="button"
              onClick={() => setAppliedNotification(null)}
              className="p-1 rounded cursor-pointer"
              style={{
                color: "var(--color-text-secondary)",
                background: "transparent",
                border: "none",
              }}
            >
              <X size={13} />
            </button>
          </div>
        </div>
      )}

      {/* ── Code Editor Body ──────────────────────────────── */}
      <div
        className="flex-1 overflow-hidden relative"
        style={{ background: "var(--color-bg)" }}
      >
        {showGitPanel && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 20 }}
            className="absolute top-4 right-4 z-50 w-96 shadow-2xl"
          >
            <GitPanel
              projectId={projectId}
              onSync={() => {
                fetchedRef.current.clear();
                setFileContents({});
              }}
            />
          </motion.div>
        )}

        <AnimatePresence mode="wait">
          {currentFile.loading ? (
            <motion.div
              key="loading"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="w-full h-full"
            >
              <EditorCodeSkeleton lines={24} />
            </motion.div>
          ) : currentFile.error ? (
            <motion.div
              key="error"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="flex flex-col items-center justify-center h-full gap-3"
            >
              <AlertCircle size={28} style={{ color: "var(--color-danger)" }} />
              <span
                className="text-xs font-sans"
                style={{ color: "var(--color-danger)" }}
              >
                {currentFile.error}
              </span>
            </motion.div>
          ) : previewMode && isMarkdown ? (
            <MarkdownPreview key="md-preview" content={codeContent} />
          ) : (
            <MonacoEditor projectId={projectId} snapshotId={snapshotId} filePath={activeTabId}
              key={`${activeTabId}-${resolvedTheme}`}
              height="100%"
              language={lang}
              theme={resolvedTheme === "light" ? "covai-light" : "covai-dark"}
              value={codeContent}
              onChange={handleChange}
              beforeMount={handleEditorWillMount}
              onMount={handleEditorDidMount}
              options={{
                readOnly: !canEdit,
                fontSize: 13.5,
                fontFamily: "var(--font-mono), monospace",
                lineHeight: 22,
                minimap: { enabled: showMinimap },
                scrollBeyondLastLine: false,
                automaticLayout: true,
                wordWrap: wordWrap ? "on" : "off",
                wrappingStrategy: "advanced",
                smoothScrolling: true,
                cursorBlinking: "smooth",
                cursorSmoothCaretAnimation: "on",
                bracketPairColorization: { enabled: true },
                guides: {
                  bracketPairs: true,
                  indentation: true,
                },
                renderLineHighlight: "all",
                renderWhitespace: "selection",
                padding: { top: 10, bottom: 10 },
                glyphMargin: true,
                lineNumbersMinChars: 3,
                scrollbar: {
                  vertical: "visible",
                  horizontal: "visible",
                  verticalScrollbarSize: 7,
                  horizontalScrollbarSize: 7,
                  useShadows: false,
                },
              }}
            />
          )}
        </AnimatePresence>
      </div>

      {/* ── Editor Status Strip ────────────────────────────── */}
      <div
        className="flex items-center justify-between flex-shrink-0 select-none"
        style={{
          height: 24,
          padding: "0 14px",
          borderTop: "1px solid var(--color-border)",
          background: "var(--color-surface)",
          fontFamily: "var(--font-mono)",
          fontSize: 11,
          color: "var(--color-text-secondary)",
        }}
      >
        <div className="flex items-center gap-4">
          <span
            className="flex items-center gap-1"
            style={{ color: "var(--color-primary)" }}
          >
            <Code2 size={11} />
            <span>{lang.charAt(0).toUpperCase() + lang.slice(1)}</span>
          </span>
          <span>{totalLines} lines</span>
          <span>
            Ln {cursorPos.line}, Col {cursorPos.col}
          </span>
        </div>
        {!isCurrentTestFile && fileCoverage?.summary && (
          <span style={{ color: "var(--color-text-secondary)", fontSize: 11 }}>
            Coverage: {fileCoverage.summary.linesPct}% (
            {fileCoverage.coveredLines?.length || 0} covered,{" "}
            {fileCoverage.uncoveredLines?.length || 0} uncovered
            {fileCoverage.failedLines?.length
              ? `, ${fileCoverage.failedLines.length} failed`
              : ""}
            )
          </span>
        )}

        <div className="flex items-center gap-3">
          <span>UTF-8</span>
          <span>Spaces: 2</span>
        </div>
      </div>
      <FileConflictDialog conflict={conflict} loading={saving} onMerged={async (content, latest) => {
        const result = await updateFileContentApi(projectId, conflict.path, content, {snapshotId:conflict.snapshotId, expectedVersion:latest.version});
        setFileContents(previous => ({...previous,[conflict.path]:{...latest,content,draft:undefined,version:result.data.version,workspaceRevision:result.data.workspaceRevision,loading:false,error:null}}));
        setConflict(null); setSaveError("");
      }} onClose={() => setConflict(null)} onReload={async () => {
        if (!conflict) return;
        downloadEditorDraft(conflict.path, conflict.draft);
        setSaving(true);
        try {
          const response = await getFileContentApi(projectId, conflict.path, { snapshotId: conflict.snapshotId });
          setFileContents(previous => ({ ...previous, [conflict.path]: { ...response.data, loading: false, error: null } }));
          setConflict(null); setSaveError("");
        } catch (err) { setSaveError(err.message); }
        finally { setSaving(false); }
      }} />
    </motion.div>
  );
}

